```javascript
/**
 * @param {number} n
 * @return {Generator<number>}
 */
var factorial = function* (n) {
    if (n === 0) {
        yield 1;
        return;
    }
    let prod = 1;
    for (let i = 1; i <= n; i++) {
        prod *= i;
        yield prod;
    }
};
